    public static SSLSocket establishSecureConnection(String host, int port) throws IOException {
        return establishSecureConnection(host, port, new String[] { "TLSv1.3", "TLSv1.2" });
    }

    public static SSLSocket establishSecureConnection(String host, int port, String[] allowedProtocols) throws IOException {
        if (host == null || host.trim().isEmpty()) throw new IllegalArgumentException("Host must not be null or empty.");
        if (port < 1 || port > 65535) throw new IllegalArgumentException("Port must be between 1 and 65535.");

        SSLSocket socket = null;
        try {
            SSLContext context = SSLContext.getDefault();
            SSLSocketFactory factory = context.getSocketFactory();
            socket = (SSLSocket) factory.createSocket(host, port);
            socket.setSoTimeout(DEFAULT_TIMEOUT_MILLIS);
            socket.setUseClientMode(true);

            SSLParameters parameters = socket.getSSLParameters();
            parameters.setEndpointIdentificationAlgorithm("HTTPS");

            Set<String> supported = new HashSet<String>(Arrays.asList(socket.getSupportedProtocols()));
            List<String> selected = new ArrayList<String>();
            if (allowedProtocols != null) {
                for (String protocol : allowedProtocols) {
                    if (protocol != null && supported.contains(protocol)) {
                        selected.add(protocol);
                    }
                }
            }
            if (selected.isEmpty()) {
                throw new IOException("No supported secure protocols available.");
            }
            parameters.setProtocols(selected.toArray(new String[selected.size()]));
            socket.setSSLParameters(parameters);
            socket.startHandshake();
            return socket;
        } catch (Exception e) {
            closeQuietly(socket);
            throw new IOException("Unable to establish secure connection.", e);
        }
    }

    public static String sendAndReceive(SSLSocket socket, String request) throws IOException {
        if (socket == null || socket.isClosed()) throw new IOException("Socket is not connected.");
        if (request == null) throw new IllegalArgumentException("Request must not be null.");

        OutputStream out = socket.getOutputStream();
        out.write(request.getBytes("UTF-8"));
        out.flush();

        InputStream in = socket.getInputStream();
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[4096];
        int read;
        try {
            while ((read = in.read(chunk)) != -1) {
                buffer.write(chunk, 0, read);
            }
        } catch (SocketTimeoutException e) {
            if (buffer.size() == 0) {
                throw new IOException("Timed out while waiting for response.", e);
            }
        }
        return buffer.toString("UTF-8");
    }

    public static String secureRequest(String host, int port, String request) throws IOException {
        SSLSocket socket = establishSecureConnection(host, port);
        try {
            return sendAndReceive(socket, request);
        } finally {
            closeQuietly(socket);
        }
    }

    public static String secureRequest(String host, int port, String request, String[] allowedProtocols) throws IOException {
        SSLSocket socket = establishSecureConnection(host, port, allowedProtocols);
        try {
            return sendAndReceive(socket, request);
        } finally {
            closeQuietly(socket);
        }
    }

    public static String getConnectionInfo(SSLSocket socket) throws IOException {
        if (socket == null || socket.isClosed()) throw new IOException("Socket is not connected.");
        SSLSession session = socket.getSession();
        StringBuilder info = new StringBuilder();
        info.append("Protocol: ").append(session.getProtocol()).append('\n');
        info.append("Cipher suite: ").append(session.getCipherSuite()).append('\n');
        info.append("Peer host: ").append(socket.getInetAddress().getHostAddress()).append('\n');
        info.append("Peer port: ").append(socket.getPort()).append('\n');
        info.append("Fingerprint: ").append(getCertificateFingerprint(socket)).append('\n');
        return info.toString();
    }

    public static String getCertificateFingerprint(SSLSocket socket) throws IOException {
        if (socket == null || socket.isClosed()) throw new IOException("Socket is not connected.");
        try {
            SSLSession session = socket.getSession();
            X509Certificate[] certificates = (X509Certificate[]) session.getPeerCertificates();
            if (certificates.length == 0) throw new IOException("Peer certificate chain is empty.");
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(certificates[0].getEncoded());
            StringBuilder hex = new StringBuilder();
            for (byte b : hash) {
                if (hex.length() > 0) hex.append(':');
                hex.append(String.format("%02X", b));
            }
            return hex.toString();
        } catch (Exception e) {
            throw new IOException("Unable to obtain peer certificate fingerprint.", e);
        }
    }

